CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', age integer CHECK(age BETWEEN 13 AND 100), sex text CHECK(sex IN ('male','female')), height numeric CHECK(height BETWEEN 100 AND 250), weight numeric CHECK(weight BETWEEN 25 AND 350), body_fat numeric CHECK(body_fat BETWEEN 1 AND 70), goal text DEFAULT 'maintenance', activity numeric DEFAULT 1.55 CHECK(activity IN (1.2,1.375,1.55,1.725,1.9)), calorie_target numeric, protein_target numeric, carb_target numeric, fat_target numeric, onboarded boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'name','')); RETURN NEW; END $$;
CREATE TRIGGER lifestyle_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.foods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, portion text NOT NULL DEFAULT '100 g', kcal numeric NOT NULL CHECK(kcal>=0), protein numeric NOT NULL CHECK(protein>=0), carbs numeric NOT NULL CHECK(carbs>=0), fat numeric NOT NULL CHECK(fat>=0), fiber numeric NOT NULL DEFAULT 0 CHECK(fiber>=0), verified boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.foods TO authenticated; GRANT SELECT ON public.foods TO anon; GRANT ALL ON public.foods TO service_role;
ALTER TABLE public.foods ENABLE ROW LEVEL SECURITY;
CREATE POLICY food_read ON public.foods FOR SELECT TO anon,authenticated USING(user_id IS NULL OR user_id=auth.uid()); CREATE POLICY food_write ON public.foods FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND verified=false);
INSERT INTO public.foods(name,kcal,protein,carbs,fat,fiber) VALUES ('Arroz integral cozido',124,2.6,25.8,1,2.7),('Peito de frango grelhado',159,32,0,2.5,0),('Banana',89,1.1,23,0.3,2.6),('Aveia em flocos',394,13.9,66.6,8.5,9.1),('Ovo cozido',146,13.3,0.6,9.5,0),('Iogurte natural',61,3.5,4.7,3.3,0),('Feijão cozido',76,4.8,13.6,0.5,8.5),('Batata-doce cozida',77,0.6,18.4,0.1,2.2);
CREATE TABLE public.exercises(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, muscle text NOT NULL, equipment text NOT NULL, description text NOT NULL DEFAULT '', video_url text);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.exercises TO authenticated; GRANT SELECT ON public.exercises TO anon; GRANT ALL ON public.exercises TO service_role;
ALTER TABLE public.exercises ENABLE ROW LEVEL SECURITY;
CREATE POLICY exercise_read ON public.exercises FOR SELECT TO anon,authenticated USING(user_id IS NULL OR user_id=auth.uid()); CREATE POLICY exercise_write ON public.exercises FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
INSERT INTO public.exercises(name,muscle,equipment,description) VALUES ('Supino reto','Peito','Barra','Mantenha os pés apoiados e desça a barra com controle.'),('Supino inclinado','Peito','Halteres','Mantenha os ombros estabilizados no banco.'),('Puxada frontal','Costas','Polia','Puxe em direção ao peito, sem balançar o tronco.'),('Remada curvada','Costas','Barra','Mantenha a coluna neutra durante o movimento.'),('Agachamento livre','Quadríceps','Barra','Desça com controle e joelhos alinhados aos pés.'),('Rosca direta','Bíceps','Halteres','Mantenha os cotovelos próximos ao corpo.'),('Tríceps na polia','Tríceps','Polia','Estenda os cotovelos sem movimentar os ombros.'),('Elevação lateral','Ombros','Halteres','Eleve os braços com controle até a linha dos ombros.');
CREATE TABLE public.daily_nutrition(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, day date NOT NULL, meal text NOT NULL, food_id uuid REFERENCES public.foods(id), details jsonb NOT NULL DEFAULT '{}', UNIQUE(id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.daily_nutrition TO authenticated; GRANT ALL ON public.daily_nutrition TO service_role;
ALTER TABLE public.daily_nutrition ENABLE ROW LEVEL SECURITY; CREATE POLICY nutrition_owner ON public.daily_nutrition FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.cardio_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, day date NOT NULL,details jsonb NOT NULL DEFAULT '{}');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cardio_logs TO authenticated; GRANT ALL ON public.cardio_logs TO service_role;
ALTER TABLE public.cardio_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY cardio_owner ON public.cardio_logs FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.workouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,day date NOT NULL,details jsonb NOT NULL DEFAULT '{}',UNIQUE(id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workouts TO authenticated; GRANT ALL ON public.workouts TO service_role;
ALTER TABLE public.workouts ENABLE ROW LEVEL SECURITY; CREATE POLICY workout_owner ON public.workouts FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.workout_sets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,workout_id uuid NOT NULL,exercise_id uuid REFERENCES public.exercises(id),details jsonb NOT NULL DEFAULT '{}', FOREIGN KEY(workout_id,user_id) REFERENCES public.workouts(id,user_id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.workout_sets TO authenticated; GRANT ALL ON public.workout_sets TO service_role;
ALTER TABLE public.workout_sets ENABLE ROW LEVEL SECURITY; CREATE POLICY set_owner ON public.workout_sets FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.fatigue_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,day date NOT NULL,details jsonb NOT NULL DEFAULT '{}',UNIQUE(user_id,day));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fatigue_logs TO authenticated; GRANT ALL ON public.fatigue_logs TO service_role;
ALTER TABLE public.fatigue_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY fatigue_owner ON public.fatigue_logs FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.habits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,details jsonb NOT NULL DEFAULT '{}',UNIQUE(id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.habits TO authenticated; GRANT ALL ON public.habits TO service_role;
ALTER TABLE public.habits ENABLE ROW LEVEL SECURITY; CREATE POLICY habit_owner ON public.habits FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.habit_completions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,habit_id uuid NOT NULL,day date NOT NULL,FOREIGN KEY(habit_id,user_id) REFERENCES public.habits(id,user_id) ON DELETE CASCADE,UNIQUE(user_id,habit_id,day));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.habit_completions TO authenticated; GRANT ALL ON public.habit_completions TO service_role;
ALTER TABLE public.habit_completions ENABLE ROW LEVEL SECURITY; CREATE POLICY completion_owner ON public.habit_completions FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.notes_pages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,parent_id uuid,details jsonb NOT NULL DEFAULT '{}',UNIQUE(id,user_id),FOREIGN KEY(parent_id,user_id) REFERENCES public.notes_pages(id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.notes_pages TO authenticated; GRANT ALL ON public.notes_pages TO service_role;
ALTER TABLE public.notes_pages ENABLE ROW LEVEL SECURITY; CREATE POLICY page_owner ON public.notes_pages FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.notes_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,page_id uuid NOT NULL,details jsonb NOT NULL DEFAULT '{}',FOREIGN KEY(page_id,user_id) REFERENCES public.notes_pages(id,user_id) ON DELETE CASCADE);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.notes_blocks TO authenticated; GRANT ALL ON public.notes_blocks TO service_role;
ALTER TABLE public.notes_blocks ENABLE ROW LEVEL SECURITY; CREATE POLICY block_owner ON public.notes_blocks FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.xp_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,day date NOT NULL,source text NOT NULL,points integer NOT NULL CHECK(points>0),UNIQUE(user_id,source));
GRANT SELECT ON public.xp_events TO authenticated; GRANT ALL ON public.xp_events TO service_role;
ALTER TABLE public.xp_events ENABLE ROW LEVEL SECURITY; CREATE POLICY xp_owner ON public.xp_events FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.reward_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p integer; s text; BEGIN IF TG_TABLE_NAME='habit_completions' THEN p:=20; s:='habit:'||NEW.habit_id||':'||NEW.day; ELSIF TG_TABLE_NAME='workouts' AND NEW.details->>'completed'='true' THEN p:=100; s:='workout:'||NEW.id; ELSE RETURN NEW; END IF; INSERT INTO public.xp_events(user_id,day,source,points) VALUES(NEW.user_id,NEW.day,s,p) ON CONFLICT(user_id,source) DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER habit_reward AFTER INSERT ON public.habit_completions FOR EACH ROW EXECUTE FUNCTION public.reward_activity(); CREATE TRIGGER workout_reward AFTER INSERT OR UPDATE ON public.workouts FOR EACH ROW EXECUTE FUNCTION public.reward_activity();
CREATE POLICY media_owner ON storage.objects FOR ALL TO authenticated USING(bucket_id='note-media' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='note-media' AND (storage.foldername(name))[1]=auth.uid()::text);